--
-- Table structure for table `abonnements`
--

CREATE TABLE `abonnements` (
  `id` char(36) NOT NULL,
  `entreprise_id` char(36) NOT NULL,
  `plan_abonnement_id` char(36) NOT NULL,
  `code_promo_id` bigint(20) UNSIGNED DEFAULT NULL,
  `date_debut` date NOT NULL,
  `date_fin` date NOT NULL,
  `date_renouvellement` date DEFAULT NULL,
  `montant` decimal(10,2) NOT NULL,
  `type_periode` varchar(255) DEFAULT NULL,
  `reduction_code_promo` decimal(5,2) DEFAULT NULL COMMENT 'Pourcentage de réduction appliqué par le code promo',
  `periode_facturation` enum('mensuel','trimestriel','semestriel','annuel') NOT NULL DEFAULT 'mensuel',
  `methode_paiement` enum('carte','virement','prelevement') NOT NULL DEFAULT 'carte',
  `facture_automatique` tinyint(1) NOT NULL DEFAULT 1,
  `nombre_personnels` int(11) NOT NULL DEFAULT 1,
  `reference_client` varchar(255) DEFAULT NULL,
  `notes_facturation` text DEFAULT NULL,
  `periodicite` enum('mensuel','annuel') NOT NULL DEFAULT 'mensuel',
  `mode_paiement` enum('carte','virement','especes','non_specifie') DEFAULT 'carte',
  `reference_paiement` varchar(255) DEFAULT NULL,
  `statut` enum('actif','inactif','essai','expire','resilie','en_attente') DEFAULT 'en_attente',
  `fonctionnalites_activees` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`fonctionnalites_activees`)),
  `limitations_specifiques` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`limitations_specifiques`)),
  `configuration` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`configuration`)),
  `notes` text DEFAULT NULL,
  `renouvellement_automatique` tinyint(1) NOT NULL DEFAULT 1,
  `renouvellement_auto` tinyint(1) NOT NULL DEFAULT 1,
  `date_resiliation` date DEFAULT NULL,
  `motif_resiliation` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

