--
-- Table structure for table `configurations_paie`
--

CREATE TABLE `configurations_paie` (
  `id` char(36) NOT NULL,
  `entreprise_id` char(36) NOT NULL,
  `nom` varchar(255) NOT NULL,
  `description` text DEFAULT NULL,
  `est_defaut` tinyint(1) NOT NULL DEFAULT 0,
  `smig` decimal(15,2) NOT NULL DEFAULT 75000.00,
  `plafond_cnps` decimal(15,2) NOT NULL DEFAULT 225000.00,
  `taux_cnps_employe` decimal(8,4) NOT NULL DEFAULT 6.3000,
  `taux_cnps_employeur` decimal(8,4) NOT NULL DEFAULT 7.7000,
  `taux_prestations_familiales` decimal(8,4) NOT NULL DEFAULT 5.7500,
  `taux_accident_travail` decimal(8,4) NOT NULL DEFAULT 2.0000,
  `taux_assurance_maladie` decimal(8,4) NOT NULL DEFAULT 0.7500,
  `abattement_igr` decimal(8,4) NOT NULL DEFAULT 20.0000,
  `baremes_igr` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`baremes_igr`)),
  `parametres_indemnites` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`parametres_indemnites`)),
  `parametres_primes` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`parametres_primes`)),
  `meta_donnees` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`meta_donnees`)),
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

