-- --------------------------------------------------------

--
-- Table structure for table `tasks`
--

CREATE TABLE `tasks` (
  `id` char(36) NOT NULL,
  `entreprise_id` char(36) NOT NULL,
  `titre` varchar(255) NOT NULL,
  `active` varchar(255) NOT NULL,
  `description` text DEFAULT NULL,
  `date_debut` datetime DEFAULT NULL,
  `date_fin` datetime DEFAULT NULL,
  `timing` varchar(255) DEFAULT NULL,
  `livrable` text DEFAULT NULL,
  `statut` varchar(255) NOT NULL DEFAULT 'en_attente',
  `type` varchar(255) NOT NULL DEFAULT 'standard',
  `priorite` varchar(255) NOT NULL DEFAULT 'moyenne',
  `etiquette` varchar(255) DEFAULT NULL,
  `est_routine` tinyint(1) NOT NULL DEFAULT 0,
  `frequence_routine` varchar(255) DEFAULT NULL,
  `jour_routine` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`jour_routine`)),
  `createur_id` char(36) DEFAULT NULL,
  `meta_donnees` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`meta_donnees`)),
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `task_assignations`
--

CREATE TABLE `task_assignations` (
  `id` char(36) NOT NULL,
  `entreprise_id` char(36) NOT NULL,
  `task_id` char(36) NOT NULL,
  `assignable_type` varchar(255) DEFAULT NULL,
  `assignable_id` char(36) DEFAULT NULL,
  `employeur_id` char(36) NOT NULL,
  `statut` varchar(255) NOT NULL DEFAULT 'en_attente',
  `progression` int(11) NOT NULL DEFAULT 0,
  `date_debut_reelle` datetime DEFAULT NULL,
  `date_fin_reelle` datetime DEFAULT NULL,
